  ON CONFLICT (poisonName) DO UPDATE SET poisonType = excluded.poisonType, costCp = excluded.costCp, poisonDescription = excluded.poisonDescription, sourceID = excluded.sourceID;
INSERT INTO Poison (poisonName, poisonType, costCp, poisonDescription, sourceID) VALUES ('Crawler Mucus', 'contact', NULL, 'A creature subjected to Crawler Mucus must succeed on a DC 13 Constitution saving throw or have the Poisoned condition for 1 minute. The creature also has the Paralyzed condition while Poisoned in this way. The creature repeats the save at the end of each of its turns, ending the effect on itself on a success.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (poisonName) DO UPDATE SET poisonType = excluded.poisonType, costCp = excluded.costCp, poisonDescription = excluded.poisonDescription, sourceID = excluded.sourceID;
INSERT INTO Poison (poisonName, poisonType, costCp, poisonDescription, sourceID) VALUES ('Essence of Ether', 'inhaled', NULL, 'A creature subjected to Essence of Ether must succeed on a DC 15 Constitution saving throw or have the Poisoned condition for 8 hours. The creature also has the Unconscious condition while Poisoned in this way. The creature wakes up if it takes damage or if another creature takes an action to shake it awake.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (poisonName) DO UPDATE SET poisonType = excluded.poisonType, costCp = excluded.costCp, poisonDescription = excluded.poisonDescription, sourceID = excluded.sourceID;
