  ON CONFLICT (poisonName) DO UPDATE SET poisonType = excluded.poisonType, costCp = excluded.costCp, poisonDescription = excluded.poisonDescription, sourceID = excluded.sourceID;
INSERT INTO Poison (poisonName, poisonType, costCp, poisonDescription, sourceID) VALUES ('Midnight Tears', 'ingested', NULL, 'A creature that ingests Midnight Tears suffers no effect until the stroke of midnight. Any effect that ends the Poisoned condition neutralizes this poison. If the poison hasn''t been neutralized before midnight, the creature makes a DC 17 Constitution saving throw, taking 31 (9d6) Poison damage on a failed save or half as much damage on a successful one.', (SELECT sourceID FROM Source WHERE sourceAbbrev = 'SRD 5.2.1'))
  ON CONFLICT (poisonName) DO UPDATE SET poisonType = excluded.poisonType, costCp = excluded.costCp, poisonDescription = excluded.poisonDescription, sourceID = excluded.sourceID;
